 /// is the natural number `n`, so the generic `power` recurrence is used over
 /// exact `IBig` arithmetic.
 pub fn push_bit_integer(n: &Nat, k: &Integer) -> Integer {
+    // Source `times_integer zero ?l = zero` absorbs on the left before the
+    // powered argument needs to be evaluated; keep that branch selective so
+    // a zero multiplier with an arbitrarily large exponent stays constant.
+    if k == &Integer::from(0u32) {
+        return k.clone();
+    }
     let base = pos(num_bit0(num_one()));
     times_integer(k.clone(), power(&base, n))
 }

test_before:
fn dequeue_generic_clone_only() {
    // Only Clone is required by the source; no Eq/Ord/Debug is available here.
    let xs = list_from_vec(vec![
        TaggedVal { id: 1 },
        TaggedVal { id: 2 },
        TaggedVal { id: 3 },
    ]);
    let (last, prefix) = dequeue(&xs);
    assert_eq!(last.id, 3u32);
    let ids: Vec<u32> = list_into_vec(prefix).into_iter().map(|v| v.id).collect();
    assert_eq!(ids, vec![1u32, 2, 3]);
}

